import React, { useState, useEffect } from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useParams } from "react-router-dom";
import private_api from "../../server/private_api";

const Avaliacao = () => {
  const { id } = useParams();
  const [avaliacoesDisponiveis, setAvaliacoesDisponiveis] = useState([]);
  const [avaliacoesConcluidas, setAvaliacoesConcluidas] = useState([]);

  useEffect(() => {
    const fetchAvaliacoes = async () => {
      try {
        const response = await private_api.get(`/alunos/${id}/avaliacoes`);

        // Separar avaliações disponíveis e concluídas
        const disponiveis = response.data.filter((av) => !av.submetida);
        const concluidas = response.data.filter((av) => av.submetida);

        setAvaliacoesDisponiveis(disponiveis);
        setAvaliacoesConcluidas(concluidas);
      } catch (error) {
        console.error("Erro ao carregar avaliações:", error);
      }
    };

    fetchAvaliacoes();
  }, [id]);

  const handleIniciarAvaliacao = (avaliacaoId) => {
    // Navegar para a página da avaliação
    window.location.href = `/avaliacao/${avaliacaoId}`;
  };

  return (
    <div
      className="container-fluid d-flex flex-column align-items-center"
      style={{
        backgroundColor: "#E7EFF4",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="nav nav-tabs mb-3 bg-white p-2 w-75 d-flex justify-content-center">
        <a className="nav-link" href="#">
          Cursos
        </a>
        <a className="nav-link" href="#">
          Aulas
        </a>
        <a className="nav-link active" href="#">
          Avaliações
        </a>
      </nav>

      <h2 className="mb-3 text-center">Avaliações</h2>

      {/* Avaliações Disponíveis */}
      <div className="bg-white p-3 rounded shadow w-75">
        <h4>Avaliações Disponíveis</h4>
        {avaliacoesDisponiveis.length > 0 ? (
          <div className="list-group">
            {avaliacoesDisponiveis.map((avaliacao) => (
              <div
                key={avaliacao.id}
                className="list-group-item d-flex justify-content-between align-items-center"
              >
                <div>
                  <h5>{avaliacao.titulo}</h5>
                  <p>{avaliacao.descricao}</p>
                  <small>
                    Disponível até:{" "}
                    {new Date(avaliacao.dataFim).toLocaleString()}
                  </small>
                </div>
                <button
                  className="btn btn-primary"
                  onClick={() => handleIniciarAvaliacao(avaliacao.id)}
                >
                  Iniciar
                </button>
              </div>
            ))}
          </div>
        ) : (
          <p>No momento, não há avaliações disponíveis para você fazer.</p>
        )}
      </div>

      {/* Avaliações Concluídas */}
      <div className="bg-white p-3 rounded shadow mt-4 w-75">
        <h4>Avaliações Concluídas</h4>
        {avaliacoesConcluidas.length > 0 ? (
          <table className="table table-bordered mt-3">
            <thead>
              <tr>
                <th>Título</th>
                <th>Pontuação</th>
                <th>Pontuação Máxima</th>
                <th>Entregue em</th>
              </tr>
            </thead>
            <tbody>
              {avaliacoesConcluidas.map((avaliacao) => (
                <tr key={avaliacao.id}>
                  <td>{avaliacao.titulo}</td>
                  <td>{avaliacao.pontuacao}</td>
                  <td>{avaliacao.pontuacaoMaxima}</td>
                  <td>{new Date(avaliacao.dataSubmissao).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </table>
        ) : (
          <p>Você ainda não concluiu nenhuma avaliação.</p>
        )}
      </div>
    </div>
  );
};

export default Avaliacao;
